/* Thin renderer over the shared lockup data (./brand, generated by
   brand/gen_logo.py). Colours resolve through the identity tokens
   (--set-a/--set-b/--overlap/--ink), so it adapts to dark mode — the site's
   stylesheet (site/src/index.css) defines them. */

import {
  LOGO_CIRCLE_A,
  LOGO_CIRCLE_B,
  LOGO_LENS,
  LOGO_STROKE,
  LOGO_TEXT_WORD,
  LOGO_VIEWBOX,
  MARK_VIEWBOX,
} from "../brand";

const Mark = () => (
  <>
    <path d={LOGO_LENS} fill="var(--overlap)" />
    <circle
      {...LOGO_CIRCLE_A}
      fill="none"
      stroke="var(--set-a)"
      strokeWidth={LOGO_STROKE}
    />
    <circle
      {...LOGO_CIRCLE_B}
      fill="none"
      stroke="var(--set-b)"
      strokeWidth={LOGO_STROKE}
    />
  </>
);

export const Logo = ({ className = "h-5 w-auto" }: { className?: string }) => (
  <svg
    viewBox={LOGO_VIEWBOX}
    className={className}
    role="img"
    aria-label="RegexSolver"
  >
    <Mark />
    <path d={LOGO_TEXT_WORD} fill="var(--ink)" />
  </svg>
);

export const LogoMark = ({
  className = "h-5 w-auto",
}: {
  className?: string;
}) => (
  <svg
    viewBox={MARK_VIEWBOX}
    className={className}
    role="img"
    aria-label="RegexSolver"
  >
    <Mark />
  </svg>
);
